// FUNCTION: BFME2 0x00324B8F size=210 name=?Rva00324B8FScrollTo@@YAXPAVGameWindow@@HH@Z evidence=?:placeholder tier=A
static void Rva00324B8FScrollTo(GameWindow *window, Int index, Int mode)
{
	if (index < 0)
		return;
	GadgetListBoxData *list = (GadgetListBoxData *)window->winGetUserData();
	if (index >= list->m_numEntries)
		return;
	GadgetListBoxEntry *rows = list->m_entries;
	GadgetListBoxEntry *row = &rows[index];
	Int y;
	switch (mode)
	{
		case 1:
			y = row->m_top - row->m_height;
			break;
		default:
			y = (2 * row->m_top - list->m_clientHeight - row->m_height) / 2;
			break;
	}
	list->m_scrollTop = 0;
	Int entry = 0;
	while (list->m_entries[entry].m_top - list->m_entries[entry].m_height < y)
		++entry;
	while (entry > 0 && list->m_totalHeight <
			rows[entry - 1].m_top - rows[entry - 1].m_height + list->m_clientHeight)
		--entry;
	list->m_scrollTop = rows[entry].m_top - rows[entry].m_height;
	if (!list->m_scrollBar &&
			rows[list->m_numEntries - 1].m_top < list->m_scrollTop + list->m_clientHeight)
		list->m_totalHeight = list->m_scrollTop + list->m_clientHeight;
	Rva003249D2(window, true);
}

// FUNCTION: BFME2 0x00324C61 size=291 name=?computeTotalHeight@@YAXPAVGameWindow@@@Z evidence=N:ledger tier=A
void computeTotalHeight(GameWindow *window)
{
	Int i, height = 0;
	Int tempHeight;
	GadgetListBoxData *list = (GadgetListBoxData *)window->winGetUserData();
	WinInstanceData *instData = window->winGetInstanceData();

	for (i = 0; i < list->m_numEntries; i++)
	{
		if (!list->m_entries[i].m_cells)
			continue;
		tempHeight = 0;

		for (Int j = 0; j < list->m_numColumns; j++)
		{
			Int cellHeight = 0;
			if (list->m_entries[i].m_cells[j].m_cellType == 1)
			{
				if ((window->winGetStatus() & 0x4000) != 0)
				{
					cellHeight = TheWindowManager->winFontHeight(instData->getFont());
				}
				else
				{
					DisplayString *displayString = (DisplayString *)list->m_entries[i].m_cells[j].m_data;
					if (displayString)
						displayString->getSize(NULL, &cellHeight);
				}
			}
			else if (list->m_entries[i].m_cells[j].m_cellType == 2)
			{
				if (list->m_entries[i].m_cells[j].m_height > 0)
					cellHeight = list->m_entries[i].m_cells[j].m_height + 1;
				else
					cellHeight = TheWindowManager->winFontHeight(instData->getFont());
			}
			if (cellHeight > tempHeight)
				tempHeight = cellHeight;
		}
		list->m_entries[i].m_height = tempHeight;
		height += (list->m_entries[i].m_height + 1);
		list->m_entries[i].m_top = height;
	}

	list->m_totalHeight = height;

	Rva003249D2(window, true);
}

// FUNCTION: BFME2 0x00324D84 size=270 name=?addImageEntry@@YAHPBVImage@@HHHPAVGameWindow@@HH@Z evidence=N:ledger tier=A

// FUNCTION: BFME2 0x00324E92 size=775 name=?GadgetListBoxMultiInput@@YA?AW4WindowMsgHandledType@@PAVGameWindow@@III@Z evidence=N:ledger tier=A

// FUNCTION: BFME2 0x00325199 size=91 name=?GadgetListBoxAddMultiSelect@@YAXPAVGameWindow@@@Z evidence=N:ledger tier=A
void GadgetListBoxAddMultiSelect(GameWindow *listbox)
{
	GadgetListBoxData *listboxData = (GadgetListBoxData *)listbox->winGetUserData();
	if (listboxData == 0 || listboxData->m_hasLength)
		return;
	listboxData->m_selections = new Int[listboxData->m_listLength];
	if (listboxData->m_selections == 0)
	{
		delete[] listboxData->m_entries;
		return;
	}
	memset(listboxData->m_selections, -1, listboxData->m_listLength * sizeof(Int));
	listboxData->m_hasLength = true;
	listbox->winSetInputFunc(GadgetListBoxMultiInput);
}

// FUNCTION: BFME2 0x003251F4 size=246 name=?GadgetListBoxUpdateColumnWidths@@YAXPAVGameWindow@@@Z evidence=N:ledger tier=A

// FUNCTION: BFME2 0x003252EA size=158 name=?GadgetListBoxSetColumnWidths@@YAXPAVGameWindow@@HPAH@Z evidence=N:ledger tier=A
void GadgetListBoxSetColumnWidths(GameWindow *listbox, int columns, int *widths)
{
	if (columns <= 0 || listbox == 0)
		return;
	GadgetListBoxData *list = (GadgetListBoxData *)listbox->winGetUserData();
	if (list == 0)
		return;
	list->m_numColumns = (short)columns;
	delete[] list->m_columnPercent;
	list->m_columnPercent = new Int[columns];
	if (widths)
	{
		for (int i = 0; i < columns; i++)
			list->m_columnPercent[i] = widths[i];
	}
	else
	{
		int each = 100 / columns;
		int rest = 100 % columns;
		for (int i = 0; i < columns; i++)
		{
			if (rest)
			{
				list->m_columnPercent[i] = each + 1;
				rest--;
			}
			else
			{
				list->m_columnPercent[i] = each;
			}
		}
	}
	GadgetListBoxUpdateColumnWidths(listbox);
}

