{
	if (window && window->winGetUserData())
		Rva00324B8FScrollTo(window, pos, 1);
}

// FUNCTION: BFME2 0x00325472 size=451 name=?addEntry@@YAHPAVUnicodeString@@HHHPAVGameWindow@@_N@Z evidence=N:ledger tier=A

// FUNCTION: BFME2 0x00325635 size=2442 name=?GadgetListBoxInput@@YA?AW4WindowMsgHandledType@@PAVGameWindow@@III@Z evidence=N:ledger tier=A

// FUNCTION: BFME2 0x00325FBF size=3071 name=?GadgetListBoxSystem@@YA?AW4WindowMsgHandledType@@PAVGameWindow@@III@Z evidence=N:ledger tier=A

// FUNCTION: BFME2 0x00326BEC size=260 name=?GadgetListBoxAddEntryText@@YAHPAVGameWindow@@VUnicodeString@@HHH_N@Z evidence=N:ledger tier=A
int GadgetListBoxAddEntryText(GameWindow *listbox, UnicodeString text, int color, int row, int column, bool overwrite)
{
	if (!listbox)
		return -1;
	if (text.isEmpty())
		text = UnicodeString((const unsigned short *)L" ");
	int index;
	GadgetListBoxImageMessage addInfo;
	addInfo.m_first = row;
	addInfo.m_second = column;
	addInfo.m_kind = 1;
	addInfo.m_image = (const Image *)&text;
	addInfo.m_flag = overwrite;
	addInfo.m_fourth = -1;
	addInfo.m_fifth = -1;

	GadgetListBoxData *listData = (GadgetListBoxData *)listbox->winGetUserData();
	bool wasFull = (listData->m_listLength <= listData->m_numEntries);
	int newEntryOffset = (wasFull) ? 0 : 1;
	int oldBottomIndex = Rva00324807(listbox);

	index = (int)TheWindowManager->winSendSystemMsg(listbox, 0x4011, (unsigned int)&addInfo, (unsigned int)color);

	if (listData->m_scrollIfAtEnd && index - oldBottomIndex == newEntryOffset && GadgetListBoxIsFull(listbox))
	{
		GadgetListBoxSetBottomVisibleEntry(listbox, index);
	}

	return index;
}

// FUNCTION: BFME2 0x00326CF0 size=249 name=?Rva00326CF0AddLines@@YAHPAVGameWindow@@VUnicodeString@@HHH_N@Z evidence=?:placeholder tier=A

// FUNCTION: BFME2 0x00326DE9 size=56 name=?Rva00326DE9Disable@@YAXPAVGameWindow@@@Z evidence=?:placeholder tier=A
void GadgetListBoxRemoveMultiSelect(GameWindow *listbox)
{
	GadgetListBoxData *listData = (GadgetListBoxData *)listbox->winGetUserData();

	if (listData->m_hasLength)
	{
		if (listData->m_selections)
		{
			delete[] listData->m_selections;
			listData->m_selections = 0;
		}
		listData->m_hasLength = false;
		listbox->winSetInputFunc(GadgetListBoxInput);
	}
}

// FUNCTION: BFME2 0x00326E21 size=378 name=?GadgetListBoxSetListLength@@YAXPAVGameWindow@@H@Z evidence=N:ledger tier=B hypothesis:K
void GadgetListBoxSetListLength(GameWindow *listbox, Int newLength)
{
	GadgetListBoxData *listboxData = (GadgetListBoxData *)listbox->winGetUserData();

	if (!listboxData)
		return;
	if (listboxData->m_numColumns < 1)
		return;

	Int columns = listboxData->m_numColumns;
	GadgetListBoxEntry *newData = new GadgetListBoxEntry[newLength];
	if (!newData)
		return;
	Int i;
	memset(newData, 0, newLength * sizeof(GadgetListBoxEntry));

	if (newLength >= listboxData->m_listLength)
	{
		memcpy(newData, listboxData->m_entries, listboxData->m_listLength * sizeof(GadgetListBoxEntry));
	}
	else
	{
		if (listboxData->m_scrollTop > newLength)
			listboxData->m_scrollTop = newLength;
		if (listboxData->m_selectPos > newLength || listboxData->m_hasLength)
			listboxData->m_selectPos = -1;
		if (listboxData->m_insertPos > newLength)
			listboxData->m_insertPos = newLength;

		listboxData->m_numEntries = newLength;
		memcpy(newData, listboxData->m_entries, newLength * sizeof(GadgetListBoxEntry));
	}

	for (i = 0; i < listboxData->m_listLength; i++)
	{
		GadgetListBoxCell *cells = listboxData->m_entries[i].m_cells;
		for (int j = columns - 1; j >= 0; j--)
		{
			if (!cells)
				break;
			if (i >= newLength)
			{
				if (cells[j].m_cellType == 1 && i >= newLength)
				{
					if (cells[j].m_data)
					{
						TheDisplayStringManager->freeDisplayString((DisplayString *)cells[j].m_data);
					}
				}
			}
		}
		if (i >= newLength)
			delete[] listboxData->m_entries[i].m_cells;
		listboxData->m_entries[i].m_cells = 0;
	}

	listboxData->m_listLength = newLength;

	if (listboxData->m_entries)
		delete[] listboxData->m_entries;
	listboxData->m_entries = newData;

	computeTotalHeight(listbox);

	if (listboxData->m_entries == 0)
		return;

	if (listboxData->m_hasLength)
	{
		GadgetListBoxRemoveMultiSelect(listbox);
		GadgetListBoxAddMultiSelect(listbox);
	}
}
